        EQ("Accessible Name перевіряють…", "The Accessible Name is checked…", ["в інспекторі доступності (Name)", "лише в CSS", "після релізу на проді єдино можливим способом", "здогадом"], 0, "Алгоритм, не око.", "An algorithm, not the eye."),
        EQ("Атрибут title як єдине ім'я іконки…", "The title attribute as an icon's only name is…", ["ненадійний для дотику й клавіатури", "достатній завжди", "кращий за aria-label", "заміняє lang"], 0, "Дайте справжнє ім'я.", "Give a real name."),
        EQ("lang на html потрібен, щоб…", "lang on html is needed so…", ["зчитувач правильної вимови", "замінити підписи полів", "сховати фокус", "вимкнути ARIA"], 0, "Мова сторінки.", "The page language."),
